from decimal import Decimal


def _line_number(value: object) -> Decimal:
    """Return a numeric sort key; missing/blank values behave as empty strings."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and assign contiguous per-order line numbers."""
    surviving = [
        row
        for row in lines
        if row.get("DEL_FLG", "") != "Y"
    ]

    ordered = sorted(
        surviving,
        key=lambda row: (
            str(row.get("ORD_ID", "")),
            _line_number(row.get("LINE_NO", "")),
        ),
    )

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for row in ordered:
        order_id = str(row.get("ORD_ID", ""))
        if order_id != current_order:
            current_order = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        copied_row = dict(row)
        copied_row["LINE_NO"] = next_line_no
        result.append(copied_row)

    return result
